<?php include "auth.php";include "conection.php";if($_SERVER['REQUEST_METHOD']!=='POST'){header("Location:tambah.php");exit;}$sid=(int)($_POST['id_siswa']??0);$kat=trim($_POST['kategori']??'');$isi=trim($_POST['isi_aspirasi']??'');if($sid<1||$kat===''||$isi==='')die("Data belum lengkap. <a href='tambah.php'>Kembali</a>");$cek=$conn->prepare("SELECT id_siswa FROM siswa WHERE id_siswa=?");$cek->bind_param("i",$sid);$cek->execute();if($cek->get_result()->num_rows===0)die("Siswa tidak ditemukan di tabel siswa. <a href='tambah_siswa.php'>Tambah siswa</a>");$tgl=date('Y-m-d H:i:s');$s=$conn->prepare("INSERT INTO id_aspirasi(tanggal,id_siswa,kategori,isi_aspirasi) VALUES(?,?,?,?)");$s->bind_param("siss",$tgl,$sid,$kat,$isi);if($s->execute()){header("Location:index.php?status=sukses");exit;}die("Gagal menyimpan: ".htmlspecialchars($s->error));